#include "RegisterGenerationScenarios.h"
#include <iostream>
#include <stdexcept>
#include <stop_token>
using namespace dft::sequential;
static unsigned n=0;static void need(bool v,const char* why){++n;if(!v)throw std::runtime_error(why);}
static void bad(const auto& r,const char* why){need(!r&&r.error().code==hier::ErrorCode::BadRequest,why);}
static auto open(const char* f,const char* top){hier::model::OpenOptions o;o.files={f};o.tops={top};auto r=hier::Design::open(o);need(r.ok(),"open own RTL");return std::move(r.value());}
static auto request(const char* top){RegisterScenarioRequest r;r.common.resolveLogic=true;std::string path=std::string(top)+".mode";r.scenarios={{"ZERO",{{{path,0},false}}},{"ONE",{{{path,0},true}}},{"BACK",{{{path,0},false}}}};return r;}
int main(int argc,char** argv){try{
 need(argc==2,"fixture");std::stop_source stop;stop.request_stop();auto d=open(argv[1],"T_direct");StatisticsRequest sr;sr.scope="T_direct.u";auto stats=registerStatistics(*d,sr);need(stats.ok()&&stats->complete&&stats->totals.facts==2,"shared original statistics");auto req=request("T_direct");
 auto c=compareRegisterScenarios(*d,*stats,req,stop.get_token());need(!c&&c.error().code==hier::ErrorCode::Cancelled,"scenario pre-cancel");auto wrong=req;wrong.scenarios.pop_back();wrong.scenarios.pop_back();bad(compareRegisterScenarios(*d,*stats,wrong),"one scenario invalid");wrong=req;wrong.scenarios[1].name=wrong.scenarios[0].name;bad(compareRegisterScenarios(*d,*stats,wrong),"duplicate scenario invalid");wrong=req;wrong.scenarios[1].name=std::string("bad")+static_cast<char>(0xff);bad(compareRegisterScenarios(*d,*stats,wrong),"new API rejects invalid UTF8");wrong=req;wrong.maxComparisons=0;bad(compareRegisterScenarios(*d,*stats,wrong),"invalid scenario comparison limit");
 wrong=req;wrong.scenarios[1].inputValues[0].input.path="absent";need(!compareRegisterScenarios(*d,*stats,wrong),"second scenario error is no half success");auto stale=*stats;stale.snapshot.snapshotId+="wrong";bad(compareRegisterScenarios(*d,stale,req),"scenario wrong snapshot");
 auto batch=compareRegisterScenarios(*d,*stats,req);need(batch.ok()&&batch->complete&&batch->scenarios.size()==3&&batch->comparisons.size()==2,"same Design reusable after errors");need(batch->events.groups.size()==2,"one original event grouping");auto& changed=batch->comparisons[0];need(changed.rows.size()==2&&changed.rows[0].status=="changed"&&changed.rows[1].status=="changed","two raw groups change");need(changed.changedTotals.factBits==13&&changed.changedTotals.coveredBits==9&&changed.changedTotals.overlapBits==4,"changed union per original state signal");need(batch->comparisons[1].changedTotals.facts==0&&batch->comparisons[1].rows[0].status=="unchanged","0/1/0 no context leak");need(stats->facts.size()==2&&d->roots().size()==1,"borrowed inputs retained");
 d.reset();stats=hier::Error{hier::ErrorCode::BadRequest,"released"};need(batch->scenarios[1].name=="ONE"&&batch->comparisons[0].changedSignals[0].coverage->coveredBits==9,"scenario report owns values after inputs released");
 auto net=open(argv[1],"T_network");sr.scope="T_network.u";auto ns=registerStatistics(*net,sr);need(ns.ok(),"network statistics");RegisterControlOptions opt;opt.resolveLogic=true;auto profile=profileRegisterControls(*net,*ns,opt);need(profile.ok()&&profile->complete,"network profile");
 auto gc=registerControlGeneration(*net,*ns,*profile,{},stop.get_token());need(!gc&&gc.error().code==hier::ErrorCode::Cancelled,"network pre-cancel");RegisterGenerationLimits gl;gl.maxEvents=0;bad(registerControlGeneration(*net,*ns,*profile,gl),"invalid event mapping limit");gl={};gl.generation.maxControls=0;bad(registerControlGeneration(*net,*ns,*profile,gl),"invalid shared generation limit");auto corrupt=*profile;corrupt.snapshotId+="wrong";bad(registerControlGeneration(*net,*ns,corrupt),"network snapshot mismatch");corrupt=*profile;corrupt.groupControls[0].clockCheck=9999;bad(registerControlGeneration(*net,*ns,corrupt),"network bad original check");need(profile->checks[0].source.has_value(),"source projection");corrupt=*profile;corrupt.checks[0].source->inverted=!corrupt.checks[0].source->inverted;bad(registerControlGeneration(*net,*ns,corrupt),"network source proof mismatch");
 auto graph=registerControlGeneration(*net,*ns,*profile);need(graph.ok()&&graph->complete&&graph->mappingComplete&&graph->graph.generators.size()==3&&graph->events.size()==2,"cross-scope clock/async generators");need(!graph->events[0].asyncIndex&&graph->events[1].asyncIndex==0&&graph->events[0].node&&graph->events[1].node,"original event order and seed nodes");gl={};gl.maxEvents=1;auto prefix=registerControlGeneration(*net,*ns,*profile,gl);need(prefix.ok()&&!prefix->complete&&!prefix->mappingComplete&&prefix->events.size()==1,"mapping cap does not claim complete network");
 net.reset();ns=hier::Error{hier::ErrorCode::BadRequest,"released"};profile=hier::Error{hier::ErrorCode::BadRequest,"released"};need(!graph->graph.generators[0].fact.ref.empty()&&!graph->graph.registerPages.empty()&&!graph->graph.nodes.back().path.empty(),"network owns original pages and new evidence");
 auto deep=open(argv[1],"T_deep");sr.scope="T_deep.u";auto ds=registerStatistics(*deep,sr);need(ds.ok(),"deep statistics");auto dr=request("T_deep");auto dc=compareRegisterGenerationScenarios(*deep,*ds,dr,{},stop.get_token());need(!dc&&dc.error().code==hier::ErrorCode::Cancelled,"deep pre-cancel");RegisterGenerationScenarioLimits dl;dl.maxRows=0;bad(compareRegisterGenerationScenarios(*deep,*ds,dr,dl),"invalid impact limit");stale=*ds;stale.facts[0].item=999999;bad(compareRegisterGenerationScenarios(*deep,stale,dr),"deep invalid original page item");wrong=dr;wrong.scenarios[1].name="";bad(compareRegisterGenerationScenarios(*deep,*ds,wrong),"deep invalid scenario name");
 auto result=compareRegisterGenerationScenarios(*deep,*ds,dr);need(result.ok()&&result->complete&&result->impacts.size()==2,"deep context reusable");need(result->analysis.comparisons[0].rows[0].status=="unchanged"&&result->analysis.comparisons[0].rows[1].status=="unchanged","direct sources unchanged");need(result->impacts[0].rows.size()==2&&result->impacts[0].rows[0].status=="changed"&&result->impacts[0].rows[1].status=="changed","deeper source changes");need(result->impacts[0].changedTotals.coveredBits==9&&result->impacts[0].changedTotals.overlapBits==4,"deep changed state union");need(result->impacts[1].changedTotals.facts==0&&result->impacts[1].rows[0].status=="unchanged","deep return context no leak");
 dl={};dl.maxRows=1;auto bounded=compareRegisterGenerationScenarios(*deep,*ds,dr,dl);need(bounded.ok()&&!bounded->complete&&bounded->rows<=1,"post row budget shared over comparisons");deep.reset();ds=hier::Error{hier::ErrorCode::BadRequest,"released"};need(result->analysis.scenarios[2].name=="BACK"&&!result->scenarios[0].generation->graph.generators[0].fact.ref.empty()&&result->impacts[0].changedSignals[0].coverage->coveredBits==9,"deep result owns batch graph and coverage");
 std::cout<<"{\"passed\":true,\"assertions\":"<<n<<"}\n";return 0;
 }catch(const std::exception& e){std::cerr<<"after "<<n<<" assertions: "<<e.what()<<'\n';return 1;}}
